void DrawShape(Rect r,int kind,Color color){string key=kind+":"+ColorUtility.ToHtmlStringRGBA(color);Texture2D t;if(!shapes.TryGetValue(key,out t)){int w=300,h=52;t=new Texture2D(w,h,TextureFormat.RGBA32,false);var pixels=new Color[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){bool inside=x>=3&&x<w-3&&y>=4&&y<h-5;if(kind==0){float nx=(x-w*.5f)/(w*.5f);inside=x>=3&&x<w-3&&y>=4&&y<h-7+Mathf.Sqrt(Mathf.Max(0,1-nx*nx))*7;}else if(kind==5||kind==6)inside=x>Mathf.Abs(y-h/2)*.7f&&x<w-Mathf.Abs(y-h/2)*.7f;else{if(x>25&&x<57&&y>h-12)inside=false;if(x>25&&x<57&&y<10)inside=true;}pixels[y*w+x]=inside?(y<7?color*.78f:color):Color.clear;}t.SetPixels(pixels);t.Apply();shapes[key]=t;}GUI.DrawTexture(new Rect(r.x+2,r.y+3,r.width,r.height),t,ScaleMode.StretchToFill,true);GUI.DrawTexture(r,t,ScaleMode.StretchToFill,true);}
List<Block> FindOwner(List<Block> list,Block target){if(list.Contains(target))return list;foreach(var b in list){var l=FindOwner(b.children,target);if(l!=null)return l;}return null;}
